/**
 * The read-only lock a workspace falls under while its subscription is not in
 * good standing. `lockReasonFor` is the pure rule; the service layer reads the
 * stored subscription and asks it at the moment of each write.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Thrown by every guarded write while the workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only: ${reason}`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * `null` means writable. A missing subscription is writable; a trial locks at
 * its period end; a cancellation locks at its cancellation date, and a
 * canceled row with no date counts as canceled now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return now.getTime() >= Date.parse(subscription.currentPeriodEnd)
        ? "trial_ended"
        : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return now.getTime() >= Date.parse(subscription.cancelAt)
        ? "canceled"
        : null;
  }
}

